PRAGMA foreign_keys=ON;
CREATE TABLE metadata(singleton INTEGER PRIMARY KEY CHECK(singleton=1),config BLOB NOT NULL CHECK(length(config)=32),signer BLOB NOT NULL CHECK(length(signer)=32));
CREATE TABLE grants(id BLOB PRIMARY KEY CHECK(length(id)=32),digest BLOB NOT NULL CHECK(length(digest)=32),creations INTEGER NOT NULL CHECK(creations>=0),mailboxes INTEGER NOT NULL CHECK(mailboxes>=0),max_creations INTEGER NOT NULL CHECK(max_creations BETWEEN 1 AND 100),max_mailboxes INTEGER NOT NULL CHECK(max_mailboxes BETWEEN 1 AND 2400)) WITHOUT ROWID;
CREATE TABLE ceremonies(id BLOB PRIMARY KEY CHECK(length(id)=32),network TEXT NOT NULL,member_count INTEGER NOT NULL CHECK(member_count BETWEEN 3 AND 16),grant_id BLOB NOT NULL REFERENCES grants(id),claim_deadline INTEGER NOT NULL,deadline INTEGER NOT NULL,terminal INTEGER NOT NULL DEFAULT 0 CHECK(terminal BETWEEN 0 AND 4)) WITHOUT ROWID;
CREATE TABLE invitations(ceremony BLOB NOT NULL REFERENCES ceremonies(id),slot INTEGER NOT NULL CHECK(slot BETWEEN 2 AND 16),hash BLOB NOT NULL CHECK(length(hash)=32),PRIMARY KEY(ceremony,slot)) WITHOUT ROWID;
CREATE TABLE claims(ceremony BLOB NOT NULL REFERENCES ceremonies(id),slot INTEGER NOT NULL CHECK(slot BETWEEN 1 AND 16),signing BLOB NOT NULL CHECK(length(signing)=32),encryption BLOB NOT NULL CHECK(length(encryption)=32),PRIMARY KEY(ceremony,slot),UNIQUE(ceremony,signing),UNIQUE(ceremony,encryption)) WITHOUT ROWID;
CREATE TABLE operations(id BLOB PRIMARY KEY CHECK(length(id)=32),ceremony BLOB NOT NULL REFERENCES ceremonies(id),digest BLOB NOT NULL CHECK(length(digest)=32),response BLOB NOT NULL,error TEXT) WITHOUT ROWID;
CREATE TABLE checkpoints(ceremony BLOB NOT NULL,slot INTEGER NOT NULL,generation INTEGER NOT NULL CHECK(generation>0),predecessor BLOB NOT NULL CHECK(length(predecessor)=32),digest BLOB NOT NULL CHECK(length(digest)=32),PRIMARY KEY(ceremony,slot),FOREIGN KEY(ceremony,slot) REFERENCES claims(ceremony,slot)) WITHOUT ROWID;
CREATE TABLE mailboxes(ceremony BLOB NOT NULL,slot INTEGER NOT NULL,relay INTEGER NOT NULL CHECK(relay BETWEEN 1 AND 3),purpose INTEGER NOT NULL CHECK(purpose IN(1,2)),mailbox BLOB NOT NULL CHECK(length(mailbox)=32),request BLOB NOT NULL,quota INTEGER NOT NULL CHECK(quota BETWEEN 1 AND 67108864),provisioned INTEGER NOT NULL DEFAULT 0 CHECK(provisioned IN(0,1)),attempts INTEGER NOT NULL DEFAULT 0 CHECK(attempts>=0),next_retry INTEGER NOT NULL DEFAULT 0 CHECK(next_retry>=0),retired INTEGER NOT NULL DEFAULT 0 CHECK(retired IN(0,1)),PRIMARY KEY(ceremony,slot,relay,purpose),UNIQUE(relay,mailbox),FOREIGN KEY(ceremony,slot) REFERENCES claims(ceremony,slot)) WITHOUT ROWID;
CREATE TABLE activation_votes(ceremony BLOB NOT NULL,slot INTEGER NOT NULL,PRIMARY KEY(ceremony,slot),FOREIGN KEY(ceremony,slot) REFERENCES claims(ceremony,slot)) WITHOUT ROWID;
